  "inlineSchema": "// ================================================================\n// LearnHub — Master Database Schema\n// This database manages tenants, plans, subscriptions, and\n// platform-level administration. One instance per deployment.\n// ================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../backend/generated/master\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ----------------------------------------------------------------\n// Tenant Registry\n// Each tenant represents an educational institute on the platform.\n// The slug is used for subdomain routing: {slug}.learnhub.lk\n// ----------------------------------------------------------------\nmodel Tenant {\n  id                  String       @id @default(uuid()) @db.Uuid\n  name                String       @db.VarChar(255)\n  slug                String       @unique @db.VarChar(100)\n  dbName              String       @map(\"db_name\") @db.VarChar(100)\n  dbHost              String       @map(\"db_host\") @db.VarChar(255)\n  dbPort              Int          @default(5432) @map(\"db_port\")\n  dbUser              String       @map(\"db_user\") @db.VarChar(100)\n  dbPasswordEncrypted String       @map(\"db_password_encrypted\") @db.Text\n  planId              String?      @map(\"plan_id\") @db.Uuid\n  status              TenantStatus @default(ACTIVE)\n  enableExams         Boolean      @default(true) @map(\"enable_exams\")\n  enableAssignments   Boolean      @default(true) @map(\"enable_assignments\")\n  enableAttendance    Boolean      @default(false) @map(\"enable_attendance\")\n  logoUrl             String?      @map(\"logo_url\") @db.Text\n  contactEmail        String?      @map(\"contact_email\") @db.VarChar(255)\n  contactPhone        String?      @map(\"contact_phone\") @db.VarChar(20)\n  address             String?      @db.Text\n  createdAt           DateTime     @default(now()) @map(\"created_at\")\n  updatedAt           DateTime     @updatedAt @map(\"updated_at\")\n\n  plan          Plan?          @relation(fields: [planId], references: [id])\n  subscriptions Subscription[]\n  invoices      Invoice[]\n\n  @@map(\"tenants\")\n}\n\nenum TenantStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  DEACTIVATED\n}\n\n// ----------------------------------------------------------------\n// Subscription Plans\n// Defines what each pricing tier includes.\n// ----------------------------------------------------------------\nmodel Plan {\n  id           String   @id @default(uuid()) @db.Uuid\n  name         String   @db.VarChar(100)\n  maxStudents  Int      @map(\"max_students\")\n  maxTeachers  Int      @map(\"max_teachers\")\n  maxCourses   Int      @map(\"max_courses\")\n  priceLkr     Decimal  @map(\"price_lkr\") @db.Decimal(10, 2)\n  featuresJson Json?    @map(\"features_json\")\n  isActive     Boolean  @default(true) @map(\"is_active\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  tenants       Tenant[]\n  subscriptions Subscription[]\n  invoices      Invoice[]\n\n  @@map(\"plans\")\n}\n\n// ----------------------------------------------------------------\n// Subscriptions\n// Tracks billing periods and payment gateway references.\n// ----------------------------------------------------------------\nmodel Subscription {\n  id                    String             @id @default(uuid()) @db.Uuid\n  tenantId              String             @map(\"tenant_id\") @db.Uuid\n  planId                String             @map(\"plan_id\") @db.Uuid\n  status                SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart    DateTime           @map(\"current_period_start\")\n  currentPeriodEnd      DateTime           @map(\"current_period_end\")\n  payhereSubscriptionId String?            @map(\"payhere_subscription_id\") @db.VarChar(255)\n  createdAt             DateTime           @default(now()) @map(\"created_at\")\n  updatedAt             DateTime           @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  plan   Plan   @relation(fields: [planId], references: [id])\n\n  @@map(\"subscriptions\")\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  PAST_DUE\n  CANCELLED\n  TRIALING\n}\n\n// ----------------------------------------------------------------\n// Platform Admins (Super Admins)\n// These are SaaS owner accounts, NOT tenant-level admins.\n// ----------------------------------------------------------------\nmodel PlatformAdmin {\n  id           String   @id @default(uuid()) @db.Uuid\n  email        String   @unique @db.VarChar(255)\n  passwordHash String   @map(\"password_hash\") @db.Text\n  firstName    String   @map(\"first_name\") @db.VarChar(100)\n  lastName     String   @map(\"last_name\") @db.VarChar(100)\n  role         String   @default(\"SUPER_ADMIN\") @db.VarChar(50)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"platform_admins\")\n}\n\n// ----------------------------------------------------------------\n// Global Settings\n// Platform-wide configurations (SaaS level)\n// ----------------------------------------------------------------\nmodel GlobalSetting {\n  id        String   @id @default(uuid()) @db.Uuid\n  key       String   @unique @db.VarChar(100)\n  value     String   @db.Text\n  category  String?  @db.VarChar(50)\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@map(\"global_settings\")\n}\n\n// ----------------------------------------------------------------\n// Platform Invoices\n// Tracks billing history for tenant subscriptions.\n// ----------------------------------------------------------------\nmodel Invoice {\n  id          String    @id @default(uuid()) @db.Uuid\n  tenantId    String    @map(\"tenant_id\") @db.Uuid\n  amount      Decimal   @db.Decimal(10, 2)\n  currency    String    @default(\"LKR\") @db.VarChar(10)\n  status      String    @default(\"PAID\") // PAID, PENDING, OVERDUE\n  billingDate DateTime  @default(now()) @map(\"billing_date\")\n  dueDate     DateTime? @map(\"due_date\")\n  paidAt      DateTime? @map(\"paid_at\")\n  planId      String    @map(\"plan_id\") @db.Uuid\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  plan   Plan   @relation(fields: [planId], references: [id])\n\n  @@map(\"platform_invoices\")\n}\n"
